package dev.eugheist.tc4modern;

import net.minecraft.client.Minecraft;
import net.minecraft.core.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.ChestBlockEntity;
import net.minecraft.world.phys.*;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;

@EventBusSubscriber(modid=TC4Modern.MODID,value=Dist.CLIENT)
public final class GolemHarvestAudit {
 static final BlockPos BASE=new BlockPos(130,121,-90),CHEST=BASE.offset(0,0,9),YOUNG=BASE.offset(4,0,4),OUTSIDE=BASE.offset(7,0,0),CANE=BASE.offset(-3,0,-3),CACTUS=BASE.offset(3,0,-3),COCOA=BASE.offset(-2,1,0),POD=BASE.offset(2,1,0);
 static StrawGolem harvester,gatherer,bellGolem;static int ticks;static long clearedLinks;static double bellWave;static volatile boolean prepared,done;static final java.util.List<BlockPos> crops=new java.util.ArrayList<>();
 static void check(boolean b,String what){if(!b)throw new IllegalStateException("TC4_HARVEST FAIL "+what);System.out.println("TC4_HARVEST PASS "+what);}
 static StrawGolem golem(ServerPlayer p,GolemMaterial m,BlockPos home,int core){var g=new StrawGolem(Golemancy.ENTITY.get(),p.level());g.material(m,true);g.home=home;g.homeFace=Direction.UP;g.moveTo(home.getX()+.5,home.getY(),home.getZ()+.5,0,0);g.getEntityData().set(StrawGolem.CORE,(byte)core);g.restrictTo(home,(int)Math.ceil(g.range()));p.level().addFreshEntity(g);return g;}
 static void setup(ServerPlayer p){
  var l=p.serverLevel();p.removeAllEffects();p.setHealth(p.getMaxHealth());p.setGameMode(GameType.CREATIVE);p.getInventory().clearContent();p.connection.teleport(BASE.getX()+8,BASE.getY()+3,BASE.getZ()-8,45,20);p.getAbilities().flying=true;p.onUpdateAbilities();
  l.getGameRules().getRule(net.minecraft.world.level.GameRules.RULE_DOMOBSPAWNING).set(false,l.getServer());l.getGameRules().getRule(net.minecraft.world.level.GameRules.RULE_RANDOMTICKING).set(0,l.getServer());l.setDayTime(6000);
  for(var entity:l.getEntitiesOfClass(Entity.class,new AABB(BASE).inflate(32)))if(!(entity instanceof net.minecraft.world.entity.player.Player))entity.discard();
  for(int x=-10;x<=23;x++)for(int z=-10;z<=13;z++)for(int y=-1;y<=4;y++)l.setBlock(BASE.offset(x,y,z),(y==-1?Blocks.STONE:Blocks.AIR).defaultBlockState(),3);
  l.getEntitiesOfClass(ItemEntity.class,new AABB(BASE).inflate(32)).forEach(Entity::discard);
  for(int x=-3;x<=3;x++){var at=BASE.offset(x,0,3);l.setBlock(at.below(),Blocks.FARMLAND.defaultBlockState(),3);var crop=(CropBlock)(x<0?Blocks.WHEAT:x<2?Blocks.CARROTS:Blocks.POTATOES);l.setBlock(at,crop.getStateForAge(crop.getMaxAge()),3);crops.add(at);}
  l.setBlock(YOUNG.below(),Blocks.FARMLAND.defaultBlockState(),3);l.setBlock(YOUNG,Blocks.WHEAT.defaultBlockState(),3);l.setBlock(OUTSIDE.below(),Blocks.FARMLAND.defaultBlockState(),3);l.setBlock(OUTSIDE,((CropBlock)Blocks.WHEAT).getStateForAge(7),3);
  var wart=BASE.offset(0,0,-3);l.setBlock(wart.below(),Blocks.SOUL_SAND.defaultBlockState(),3);l.setBlock(wart,Blocks.NETHER_WART.defaultBlockState().setValue(NetherWartBlock.AGE,3),3);crops.add(wart);
  var melon=BASE.offset(-4,0,0);l.setBlock(melon,Blocks.MELON.defaultBlockState(),3);crops.add(melon);
  for(var at:java.util.List.of(CANE,CACTUS)){l.setBlock(at.below(2),Blocks.STONE.defaultBlockState(),3);l.setBlock(at.below(),Blocks.SAND.defaultBlockState(),3);if(at.equals(CANE))l.setBlock(at.below().west(),Blocks.WATER.defaultBlockState(),3);for(int y=0;y<3;y++)l.setBlock(at.above(y),(at.equals(CANE)?Blocks.SUGAR_CANE:Blocks.CACTUS).defaultBlockState(),3);}
  l.setBlock(COCOA.east(),Blocks.JUNGLE_LOG.defaultBlockState(),3);l.setBlock(COCOA,Blocks.COCOA.defaultBlockState().setValue(CocoaBlock.FACING,Direction.EAST).setValue(CocoaBlock.AGE,2),3);crops.add(COCOA);
  l.setBlock(POD.above(),TC4Modern.GREATWOOD_LOG.get().defaultBlockState(),3);l.setBlock(POD,BasicsContent.MANA_POD.get().defaultBlockState().setValue(ManaPodBlock.AGE,7),3);crops.add(POD);
  harvester=golem(p,GolemMaterial.TALLOW,BASE,-1);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Golemancy.HARVEST.get(),2));harvester.mobInteract(p,InteractionHand.MAIN_HAND);check(harvester.core()==3&&p.getMainHandItem().getCount()==1,"harvest installation consumes one even creative");p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Golemancy.upgrade(2),3));harvester.mobInteract(p,InteractionHand.MAIN_HAND);harvester.mobInteract(p,InteractionHand.MAIN_HAND);check(harvester.range()==24&&harvester.upgrades(2)==2&&p.getMainHandItem().getCount()==1,"water duplicates extend range to24 within two tallow slots");harvester.mobInteract(p,InteractionHand.MAIN_HAND);check(p.getMainHandItem().getCount()==1,"third upgrade rejected without consumption");
  p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);harvester.mobInteract(p,InteractionHand.MAIN_HAND);check(p.containerMenu==p.inventoryMenu,"harvest has no filter inventory in original");
  var earth=bellGolem=golem(p,GolemMaterial.THAUMIUM,BASE.offset(-6,0,5),-1);check(earth.installUpgrade(1)&&earth.installUpgrade(1)&&!earth.installUpgrade(1)&&earth.carryLimit()==64&&earth.strength()==6&&earth.getAttributeValue(Attributes.ATTACK_DAMAGE)==10,"two earth upgrades original carry and strength");var saved=new CompoundTag();earth.addAdditionalSaveData(saved);var copy=new StrawGolem(Golemancy.ENTITY.get(),l);copy.readAdditionalSaveData(saved);check(copy.upgrades(1)==2&&copy.carryLimit()==64,"upgrades survive entity save/load");var item=earth.asItem();var restored=new StrawGolem(Golemancy.ENTITY.get(),l);restored.material(GolemMaterial.THAUMIUM,true);restored.restoreItem(item);check(restored.upgrades(1)==2&&restored.carryLimit()==64,"upgrades survive bell item payload");
  var air=golem(p,GolemMaterial.FLESH,BASE.offset(-5,0,5),-1);check(air.installUpgrade(0)&&air.installUpgrade(0)&&Math.abs(air.getAttributeValue(Attributes.MOVEMENT_SPEED)-GolemMaterial.FLESH.speed*1.3)<.00001,"two air upgrades speed +30 percent");
  l.setBlock(CHEST,Blocks.CHEST.defaultBlockState(),3);gatherer=golem(p,GolemMaterial.STRAW,CHEST.above(),2);check(gatherer.installUpgrade(2)&&!gatherer.installUpgrade(0)&&gatherer.range()==20,"straw one upgrade slot");gatherer.filters.setItem(0,new ItemStack(Items.DIAMOND));var distant=new ItemEntity(l,CHEST.getX()+18.5,CHEST.getY(),CHEST.getZ()+.5,new ItemStack(Items.DIAMOND));distant.setNoPickUpDelay();distant.setDeltaMovement(Vec3.ZERO);l.addFreshEntity(distant);
  var r=CrucibleRecipes.byKey().get("CoreHarvest");check(r!=null&&r.aspects.visSize()==10&&r.key.equals("COREHARVEST"),"original harvest crucible recipe");for(String key:java.util.List.of("UpgradeAir","UpgradeEarth","UpgradeWater")){var recipe=ArcaneRecipes.entries().stream().filter(e->e.key().equals(key)).findFirst().orElseThrow();var grid=recipe.ingredients().stream().map(i->i.getItems()[0].copy()).toList();check(recipe.matches(grid,java.util.Set.of(recipe.research()))&&!recipe.matches(grid,java.util.Set.of()),"original arcane upgrade recipe and research "+key);}
  prepared=true;
 }
 static void finish(ServerPlayer p){var l=p.serverLevel();for(var at:crops)if(!l.isEmptyBlock(at))System.out.println("TC4_HARVEST remaining "+at+" "+l.getBlockState(at));for(var at:crops)check(l.isEmptyBlock(at),"natural harvest at "+at);check(l.getBlockState(YOUNG).is(Blocks.WHEAT)&&l.getBlockState(YOUNG).getValue(CropBlock.AGE)==0,"young crop untouched");check(l.getBlockState(OUTSIDE).is(Blocks.WHEAT),"crop beyond range/4 untouched");check(l.getBlockState(CANE).is(Blocks.SUGAR_CANE)&&l.isEmptyBlock(CANE.above()),"sugar cane base preserved");check(l.getBlockState(CACTUS).is(Blocks.CACTUS)&&l.isEmptyBlock(CACTUS.above()),"cactus base preserved");check(l.getEntitiesOfClass(ItemEntity.class,new AABB(BASE).inflate(10)).stream().anyMatch(e->e.getItem().is(Items.WHEAT)),"harvest remains dropped for a separate gather golem");check(GolemAudit.count((ChestBlockEntity)l.getBlockEntity(CHEST),Items.DIAMOND)==1,"water-upgraded gatherer naturally retrieves item18 blocks away");
  p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Golemancy.BELL.get()));var bell=(Golemancy.Bell)Golemancy.BELL.get();var pos=harvester.blockPosition();bell.onLeftClickEntity(p.getMainHandItem(),p,harvester);var placer=l.getEntitiesOfClass(ItemEntity.class,new AABB(pos).inflate(3)).stream().filter(e->e.getItem().is(Golemancy.placer(GolemMaterial.TALLOW).get())).findFirst().orElseThrow().getItem();var roundtrip=new StrawGolem(Golemancy.ENTITY.get(),l);roundtrip.material(GolemMaterial.TALLOW,true);roundtrip.restoreItem(placer);check(roundtrip.core()==3&&roundtrip.upgrades(2)==2,"actual bell retrieves harvest core and upgrades");done=true;}
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("tc4modern.golemHarvestAuditOnly"))return;var mc=Minecraft.getInstance();if(mc.player==null)return;ticks++;if(ticks==10&&mc.player.isDeadOrDying())mc.player.respawn();var server=mc.getSingleplayerServer();var id=mc.player.getUUID();if(ticks==40)server.execute(()->setup(server.getPlayerList().getPlayer(id)));if(ticks==210)server.execute(()->{var p=server.getPlayerList().getPlayer(id);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(ArcaneBore.BORE.get()));var item=new ItemEntity(p.level(),p.getX()-2,p.getY()-1,p.getZ()+2,new ItemStack(ArcaneBore.BORE.get()));item.setDeltaMovement(Vec3.ZERO);item.setNoGravity(true);item.setPickUpDelay(32767);p.level().addFreshEntity(item);});
 if(ticks==240){var model=mc.getItemRenderer().getModel(new ItemStack(ArcaneBore.BORE.get()),mc.level,mc.player,0);check(!model.getQuads(null,null,net.minecraft.util.RandomSource.create()).isEmpty(),"bore item baked model");try(var reader=mc.getResourceManager().openAsReader(AlchemyContent.id("models/item/arcane_bore.json"))){var json=com.google.gson.JsonParser.parseReader(reader).getAsJsonObject();for(var el:json.getAsJsonArray("elements"))for(var entry:el.getAsJsonObject().getAsJsonObject("faces").entrySet())for(var uv:entry.getValue().getAsJsonObject().getAsJsonArray("uv"))check(uv.getAsDouble()>=0&&uv.getAsDouble()<=16,"bore item UV stays on texture");}catch(java.io.IOException ex){throw new java.io.UncheckedIOException(ex);}LiquidDeathAudit.shot(mc,"arcane-bore-item-fixed.png");}
 if(ticks==200){check(prepared&&GolemClient.rendered>0,"upgraded golems rendered");LiquidDeathAudit.shot(mc,"golem-harvest-working.png");}if(ticks%200==0)server.execute(()->System.out.println("TC4_HARVEST progress remaining="+crops.stream().filter(at->!harvester.level().isEmptyBlock(at)).count()+" golem="+harvester.position()+" alive="+harvester.isAlive()+" left="+crops.stream().filter(at->!harvester.level().isEmptyBlock(at)).toList()));if(ticks==900)server.execute(()->{var p=server.getPlayerList().getPlayer(id);var bell=new ItemStack(Golemancy.BELL.get());p.setItemInHand(InteractionHand.MAIN_HAND,bell);((Golemancy.Bell)bell.getItem()).interactLivingEntity(bell,p,bellGolem,InteractionHand.MAIN_HAND);for(var side:java.util.List.of(Direction.UP,Direction.EAST,Direction.SOUTH)){var pos=BASE.offset(-3,0,6);p.level().setBlock(pos,Blocks.STONE.defaultBlockState(),3);var context=new net.minecraft.world.item.context.UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(pos),side,pos,false));((Golemancy.Bell)bell.getItem()).onItemUseFirst(bell,context);}p.connection.teleport(BASE.getX()+2,BASE.getY()+3,BASE.getZ()+12,135,25);p.containerMenu.broadcastChanges();});if(ticks==940){check(GolemBellClient.homes>0&&GolemBellClient.marks>0&&GolemBellClient.links>0,"native bell home markers and flowing script rendered");bellWave=GolemBellClient.lastWave;for(String texture:java.util.List.of("misc/home.png","misc/mark.png","misc/script.png","blocks/empty.png"))check(mc.getResourceManager().getResource(AlchemyContent.id("textures/"+texture)).isPresent(),"original bell texture "+texture);LiquidDeathAudit.shot(mc,"golem-bell-original-effect.png");}if(ticks==950)check(bellWave!=GolemBellClient.lastWave,"bell ribbons animate between frames");if(ticks==960)server.execute(()->{var p=server.getPlayerList().getPlayer(id);Golemancy.Bell.reset(p);p.containerMenu.broadcastChanges();});if(ticks==980){check(NoteData.tag(mc.player.getMainHandItem()).getList("markers",10).isEmpty(),"bell reset removes visible markers");clearedLinks=GolemBellClient.links;}if(ticks==1000)check(GolemBellClient.links==clearedLinks,"reset stops rendering old links");if(ticks==5000)server.execute(()->finish(server.getPlayerList().getPlayer(id)));if(ticks==5020){check(done,"all harvest and upgrade checks finished");for(var key:java.util.List.of("COREHARVEST","UPGRADEAIR","UPGRADEEARTH","UPGRADEWATER"))check(BasicsBookRecipes.researchIcon(key)!=null,"research icon "+key);LiquidDeathAudit.shot(mc,"golem-harvest-finished.png");System.out.println("TC4_HARVEST ALL PASS");mc.stop();}}
}
